import type { StockPhoto } from '@aglyn/aglyn/plugin-manager/stock-photo-provider'

/**
 * WHAT PIXABAY ANSWERS THE SEARCHES OF THREE TEST SITES, RE-FETCHED ON
 * 2026-10-28 (AGL-4092).
 *
 * Three guided starts in the test workspace, one per fictional business:
 * Berm & Bolt Moto Parts (a dirt bike and ATV parts shop), Pit Row Tacos (a
 * taco trailer) and Rut Runners Racing (an amateur motocross team). Their
 * media libraries record only the search that found each photo
 * (`stockPhoto.query`), so every search they sent that placed a photo at
 * issue, and every search the fixes now send in its place, was asked again,
 * read-only, as the source asks it (`aiStockSearchRequest` through the
 * provider's `pixabaySearchParams`): its words, orientation, size and, for a
 * people search, the people category. 40 searches and 2 photos by id.
 *
 * Each list is the first 20 hits of the answer, in its order, plus any later
 * hit that is a photo production placed; the three tire searches keep all 40
 * (the shoot two tire products shared stands 27th and 34th in one of them).
 * Two photos production placed were no longer answered by their search on
 * 2026-10-28 and are read by id and put first in it, marked below: the
 * European alley for "taco around town" and the man posing with a street
 * bike for "motocross race team gate drop". A hit's tags are the API's, up to
 * 30 as the provider now keeps them; its size is its large copy's. Each
 * contributor is a number, one per contributor, so a shoot still reads as
 * one (`aiStockSameShoot`); no name, no contact details.
 *
 * The answers drift: a replay holds a slot to "never this photo when it is
 * offered" and to what the photo it takes says it is, never to an id that
 * only today's answer gives.
 */

const hit = (id: number, width: number, height: number, slug: string, contributor: number, tags: string): StockPhoto =>
  ({
    provider: 'pixabay',
    id: String(id),
    width,
    height,
    pageUrl: `https://pixabay.com/photos/${slug}-${id}/`,
    photographer: `Pixabay contributor ${contributor}`,
    tags: tags.split(', ').filter(Boolean),
    downloadUrl: `https://pixabay.com/get/g${id}_1280.jpg`,
  }) as StockPhoto

